'use strict';
const stimulusWindow=$('stimulusWindow'),monitorHandle=$('monitorDragHandle');let monitorPlaceholder=null,monitorMove=null,monitorResize=null,monitorPlacement=null;
const resizeGrip=document.createElement('div');resizeGrip.className='monitorResizeGrip';resizeGrip.title='Drag to resize stimulus monitor';resizeGrip.setAttribute('aria-label','Resize stimulus monitor');stimulusWindow.appendChild(resizeGrip);
function monitorSave(){try{if(monitorPlacement)localStorage.setItem('visual-rig-monitor-position',JSON.stringify(monitorPlacement));else localStorage.removeItem('visual-rig-monitor-position');}catch{}}
function positionMonitor(){if(!monitorPlacement)return;const maxWidth=Math.max(160,Math.min(window.innerWidth-16,(window.innerHeight-74)*1.5));monitorPlacement.width=Math.max(Math.min(220,maxWidth),Math.min(maxWidth,monitorPlacement.width));stimulusWindow.style.width=monitorPlacement.width+'px';const height=stimulusWindow.getBoundingClientRect().height;monitorPlacement.left=Math.max(8,Math.min(window.innerWidth-monitorPlacement.width-8,monitorPlacement.left));monitorPlacement.top=Math.max(8,Math.min(window.innerHeight-height-8,monitorPlacement.top));stimulusWindow.style.left=monitorPlacement.left+'px';stimulusWindow.style.top=monitorPlacement.top+'px';}
function floatMonitor(){if(monitorPlacement)return;const r=stimulusWindow.getBoundingClientRect();monitorPlaceholder=document.createElement('div');monitorPlaceholder.className='monitorPlaceholder';monitorPlaceholder.style.height=r.height+'px';monitorPlaceholder.textContent='Stimulus monitor is floating. Drag its header to reposition, or click Dock.';stimulusWindow.before(monitorPlaceholder);document.body.appendChild(stimulusWindow);stimulusWindow.classList.add('floatingMonitor');monitorPlacement={left:r.left,top:r.top,width:r.width};positionMonitor();}
function dockMonitor(){if(!monitorPlacement)return;monitorPlaceholder.replaceWith(stimulusWindow);monitorPlaceholder=null;stimulusWindow.classList.remove('floatingMonitor');stimulusWindow.style.width='';stimulusWindow.style.left='';stimulusWindow.style.top='';monitorPlacement=null;monitorSave();}
monitorHandle.addEventListener('pointerdown',e=>{if(e.target.closest('button,select,input'))return;e.preventDefault();floatMonitor();monitorMove={x:e.clientX,y:e.clientY,left:monitorPlacement.left,top:monitorPlacement.top};monitorHandle.setPointerCapture(e.pointerId);});monitorHandle.addEventListener('pointermove',e=>{if(!monitorMove)return;monitorPlacement.left=monitorMove.left+e.clientX-monitorMove.x;monitorPlacement.top=monitorMove.top+e.clientY-monitorMove.y;positionMonitor();});monitorHandle.addEventListener('pointerup',()=>{monitorMove=null;monitorSave();});monitorHandle.addEventListener('pointercancel',()=>{monitorMove=null;monitorSave();});
resizeGrip.addEventListener('pointerdown',e=>{e.preventDefault();floatMonitor();monitorResize={x:e.clientX,width:monitorPlacement.width};resizeGrip.setPointerCapture(e.pointerId);});resizeGrip.addEventListener('pointermove',e=>{if(!monitorResize)return;monitorPlacement.width=monitorResize.width+e.clientX-monitorResize.x;positionMonitor();});resizeGrip.addEventListener('pointerup',()=>{monitorResize=null;monitorSave();});resizeGrip.addEventListener('pointercancel',()=>{monitorResize=null;monitorSave();});
$('dockMonitor').onclick=dockMonitor;window.addEventListener('resize',()=>{positionMonitor();monitorSave();});
